# NB: C10 mappings are more specific than Caffe2 mappings, so run them
# first

# FastPT/DTK-only additions retained after the PyTorch 2.12 mapping baseline.
# Values deliberately use the target direct-string mapping format.
def _fastpt_dtk_version() -> str:
    version_file = os.path.join(os.environ.get("ROCM_PATH", ""), ".info", "rocm_version")
    try:
        with open(version_file, encoding="utf-8") as handle:
            return handle.readline().strip().replace(".", "")[:-1]
    except OSError:
        return "9999"


dtk_version = _fastpt_dtk_version()
CUDATODTK_DICT.update({"__NVCC__": "__HIPCC__"})

